/**
 * Narrative test harness bundler (Claude 4). Usage: node tools/narrative/build.mjs <entry.ts> [full|v2]
 * full: Registry = every src/data module (registry-full.ts, regenerated by gen-registry.sh); v2: in-memory registry.
 * OUT env = output file (default: a per-process temp file); prints the output path.
 */
import { build } from 'esbuild';
import path from 'node:path';
import fs from 'node:fs';
import os from 'node:os';
import { fileURLToPath } from 'node:url';
const here = path.dirname(fileURLToPath(import.meta.url));
const SRC = path.resolve(here, '../../src');
const mode = process.argv[3] ?? 'full';
const out = process.env.OUT ?? path.join(os.tmpdir(), `nar-${process.pid}-${path.basename(process.argv[2], '.ts')}.mjs`);
await build({
  entryPoints: [path.resolve(process.argv[2])], bundle: true, platform: 'node', format: 'esm', outfile: out,
  define: { 'import.meta.env.DEV': 'false' }, logLevel: 'error',
  plugins: [{ name: 'alias', setup(b) {
    b.onResolve({ filter: /^@\/systems$/ }, () => ({ path: path.join(here, 'systems-stub.ts') }));
    b.onResolve({ filter: /Registry$/ }, () => ({ path: path.join(here, mode === 'v2' ? 'registry-v2.ts' : 'registry-full.ts') }));
    b.onResolve({ filter: /^@\// }, (a) => { const p = path.join(SRC, a.path.slice(2)); return { path: fs.existsSync(p + '.ts') ? p + '.ts' : path.join(p, 'index.ts') }; });
    b.onResolve({ filter: /^phaser$/ }, () => ({ path: 'phaser', external: true }));
  } }],
});
console.log(out);
